                output[row_above][nc] = 5

    # 8s 2 rows below, spanning 5 cols centered at c
    row_below = r + 2
    for dc in range(-2, 3):
        nc = c + dc
        if 0 <= nc < cols:
            if 0 <= row_below < rows:
                output[row_below][nc] = 8

